const item = $input.first().json.body || $input.first().json;

// Context Expansion check & Koray Directive injection
const isShort = (item.content || '').length < 150;
item.expansion_instruction = isShort 
  ? 'Sumber sangat ringkas. Wajib lakukan rekonstruksi konteks sejarah selebritas, preseden kasus serupa, analisis jejak digital masa lalu, serta spektrum polarisasi netizen minimal 1000 kata.'
  : 'Kembangkan narasi kronologi berimbang berbasis jejak digital dan verifikasi data.';

return [{ json: item }];

const raw = $input.first().json;
const contentString = raw.choices[0].message.content;
const articleData = JSON.parse(contentString);

if (!articleData.slug) {
  articleData.slug = articleData.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

articleData.published_at = new Date().toISOString();

// Siapkan parameter generate karikatur Cloudflare Workers AI
const mainEntity = (articleData.entities && articleData.entities.length > 0) ? articleData.entities[0] : 'Indonesian celebrity';
articleData.caricature_payload = {
  celebrity: mainEntity,
  event: articleData.caricature_event_prompt || articleData.title
};

return [{ json: articleData }];
